interface WindowsModeProfile {
  role: WindowsRole;
  label: string;
  views: ViewId[];
  localActions: IntentId[];
}

interface WindowsFixtureRow {
  id: string;
  view: ViewId;
  title: string;
  status: "local" | "queued" | "blocked" | "disabled";
  detail: string;
}

interface WindowsIntegrationCard {
  id: string;
  views: ViewId[];
  title: string;
  status: WindowsIntegrationStatus;
  detail: string;
  sourceIds: readonly string[];
}

interface WindowsOperatorCommand {
  id: string;
  title: string;
  command: string;
  surface: "windows-run" | "mesh-discovery" | "xbee-radio" | "firmware-flash";
  sourceIds: readonly string[];
}

